package cn.local.rainreminder;
import android.content.Context;import org.json.*;import java.time.*;import java.util.*;import java.util.regex.*;
final class SchoolSchedule {
 static LocalDate firstMonday(String anchor){Matcher m=Pattern.compile("第\\s*(\\d+)\\s*周[^0-9]*(\\d{4}-\\d{1,2}-\\d{1,2})\\s*[~～至—-]\\s*(\\d{4}-\\d{1,2}-\\d{1,2})").matcher(anchor);if(!m.find())throw new IllegalArgumentException("没有读到可靠的周次和日期，请先切到周课表");int week=Integer.parseInt(m.group(1));LocalDate from=LocalDate.parse(m.group(2),java.time.format.DateTimeFormatter.ofPattern("yyyy-M-d")),end=LocalDate.parse(m.group(3),java.time.format.DateTimeFormatter.ofPattern("yyyy-M-d"));if(week<1||week>40||from.getDayOfWeek()!=DayOfWeek.MONDAY||!end.equals(from.plusDays(6)))throw new IllegalArgumentException("校历周次与日期不一致");return from.minusWeeks(week-1);}
 static Set<Integer> weeks(String raw){String cleaned=raw.replaceAll("\\s+","").replace('，',',').replace('（','(').replace('）',')');Set<Integer> out=new TreeSet<>();for(String piece:cleaned.split(",")){Matcher m=Pattern.compile("(\\d+)(?:[-~～](\\d+))?周(?:\\(([单双])\\))?").matcher(piece);if(!m.matches())throw new IllegalArgumentException("无法解析周次："+raw);int start=Integer.parseInt(m.group(1)),end=m.group(2)==null?start:Integer.parseInt(m.group(2));if(start<1||end<start||end>40)throw new IllegalArgumentException("周次范围不正确");for(int w=start;w<=end;w++)if(m.group(3)==null||("单".equals(m.group(3))?w%2==1:w%2==0))out.add(w);}return out;}
 static JSONArray events(Context c,JSONObject data,String anchor)throws Exception{LocalDate first=firstMonday(anchor);String term=data.optString("term");if(!term.matches("(?s).*\\d{4}-\\d{4}.*第[一二12]学期.*"))throw new IllegalArgumentException("没有读到学期名称");Matcher year=Pattern.compile("(\\d{4})-(\\d{4})").matcher(term);year.find();int y=Integer.parseInt(year.group(1));boolean autumn=term.contains("第一")||term.contains("第1");if(autumn?(first.getYear()!=y||first.getMonthValue()<7):(first.getYear()!=y+1||first.getMonthValue()>6))throw new IllegalArgumentException("学期与周课表日期不一致，请使用当前学期");List<LocalTime[]> times=ImportActivity.parseTimes(ImportActivity.periodTimes(c));JSONArray records=data.getJSONArray("records"),out=new JSONArray();Set<String> seen=new HashSet<>();for(int n=0;n<records.length();n++){JSONObject r=records.getJSONObject(n);int day=r.getInt("day");String title=r.getString("title").trim(),raw=r.getString("periodWeeks").replace('（','(').replace('）',')');Matcher m=Pattern.compile("\\((\\d+)(?:[-~～](\\d+))?节\\)(.+)").matcher(raw.replaceAll("\\s+",""));if(day<1||day>7||title.isEmpty()||!m.matches())throw new IllegalArgumentException("课程节次不完整："+title);int start=Integer.parseInt(m.group(1)),end=m.group(2)==null?start:Integer.parseInt(m.group(2));if(start<1||end<start||end>times.size())throw new IllegalArgumentException("请先在课表设置补全节次时间");for(int w:weeks(m.group(3))){LocalDate date=first.plusWeeks(w-1).plusDays(day-1);long from=date.atTime(times.get(start-1)[0]).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli(),until=date.atTime(times.get(end-1)[1]).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();if(until<=from)throw new IllegalArgumentException("节次结束时间不正确");String place=r.optString("place");if(!seen.add(title+"|"+place+"|"+from+"|"+until))continue;JSONObject event=Agenda.create(title,place,from,until,true);event.put("lead",Agenda.prefs(c).getInt("defaultLead",10)).put("scanLead",Agenda.prefs(c).getInt("defaultScanLead",3)).put("source","school").put("schoolTerm",term).put("schoolWeek",w).put("periods",start+"-"+end).put("importWeek",Agenda.weekOf(from).toString()).put("ocr","");out.put(event);}}if(out.length()==0)throw new IllegalArgumentException("未读取到已排定时间的课程");return out;}
}
